      's.rules.lead': 'Lascia che il pannello reagisca a ciò che accade su questo computer: mostra la pagina AI quando Claude ha bisogno di te, la pagina musica quando qualcosa è in riproduzione, un cartello «on air» durante le chiamate. Una regola scatta quando la sua condizione inizia; con «solo finché dura» il telefono torna dov\'era (e un valore inviato viene rimosso) quando la condizione finisce.',
